import { formatMoney } from '../../../core/format/money';
import { Codepage } from '../printing/escpos';
import { LayoutBuilder, PrintLayout, Translate } from '../printing/receipt-layout';

/**
 * Gift cards (Mehrzweck-Gutschein, ADR-0020), pure client rules. The code is generated by the API and returned once;
 * the client only normalizes what the cashier types or scans, formats it and checks amounts before asking the API.
 */

/** Same alphabet as the API (no 0/O, 1/I): 16 characters, shown as XXXX-XXXX-XXXX-XXXX. */
export const GIFT_CARD_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
export const GIFT_CARD_CODE_LENGTH = 16;

/** API defaults `Pos:GiftCard:MinMinor` / `MaxMinor` (5,00 € – 500,00 €). The API stays authoritative. */
export const GIFT_CARD_LIMITS = { minMinor: 500, maxMinor: 50_000 } as const;
export const GIFT_CARD_QUICK_AMOUNTS = [1_000, 2_000, 2_500, 5_000, 10_000];

/** Upper-cases, removes spaces and dashes; null when what remains is not a code (like `GiftCardCode.Normalize`). */
export function normalizeGiftCardCode(input: string | null | undefined): string | null {
  if (!input || input.length > 64) return null;
  const compact = input.replace(/[\s-]/g, '').toUpperCase();
  if (compact.length !== GIFT_CARD_CODE_LENGTH) return null;
  return [...compact].every((c) => GIFT_CARD_ALPHABET.includes(c)) ? compact : null;
}

/** Groups of four for display and printing; accepts a normalized or a formatted code. */
export function formatGiftCardCode(code: string): string {
  const compact = code.replace(/[\s-]/g, '').toUpperCase();
  return compact.match(/.{1,4}/g)?.join('-') ?? '';
}

/** What receipts and lists show instead of the code. */
export function maskedGiftCard(last4: string | null | undefined): string {
  return `••••-${(last4 ?? '').toUpperCase()}`;
}

/** Formats while typing: keeps only code characters and inserts the dashes (max 16 characters). */
export function typingGiftCardCode(input: string): string {
  const compact = input
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, '')
    .slice(0, GIFT_CARD_CODE_LENGTH);
  return formatGiftCardCode(compact);
}

export type GiftCardAmountError = 'invalid' | 'tooLow' | 'tooHigh' | null;

export function giftCardAmountError(minor: number | null, limits: { minMinor: number; maxMinor: number } = GIFT_CARD_LIMITS): GiftCardAmountError {
  if (minor === null || !Number.isSafeInteger(minor) || minor <= 0) return 'invalid';
  if (minor < limits.minMinor) return 'tooLow';
  if (minor > limits.maxMinor) return 'tooHigh';
  return null;
}

/**
 * Amount to take from a gift card: what it still has, but not more than the part of the sale that may be paid by gift
 * card (gift card lines themselves cannot be paid with a gift card).
 */
export function giftCardPaymentAmount(balanceMinor: number, payableMinor: number): number {
  return Math.max(0, Math.min(balanceMinor, payableMinor));
}

export interface IssuedGiftCard {
  id: string;
  /** Full code — only in the response of the request that created the card (null on reads and replays). */
  code: string | null;
  codeLast4: string;
  amountMinor: number;
  expiresOn: string | null;
}

/** Calendar date "2029-12-31" → "31.12.2029" without a time-zone shift. */
export function dateOnly(value: string | null | undefined): string {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(value ?? '');
  return m ? `${m[3]}.${m[2]}.${m[1]}` : '';
}

/** Thermal voucher slip: title, amount, the full code (large), validity. Printed only while the code is known. */
export function voucherLayout(
  card: IssuedGiftCard,
  o: { width: number; codepage: Codepage; t: Translate; sellerLines: string[]; receiptNumber: number | null },
): PrintLayout {
  const b = new LayoutBuilder(o.width, o.codepage);
  const t = o.t;
  for (const l of o.sellerLines) b.text(l, { align: 'center' });
  if (o.sellerLines.length) b.feed();
  b.text(t('pos.giftCards.slip.title'), { align: 'center', bold: true, size: 2 }).feed();
  b.text(formatMoney(card.amountMinor), { align: 'center', bold: true, size: 2 }).feed();
  b.text(t('pos.giftCards.slip.code'), { align: 'center' });
  b.text(card.code ? formatGiftCardCode(card.code) : maskedGiftCard(card.codeLast4), { align: 'center', bold: true });
  b.feed();
  if (card.expiresOn) b.pair(t('pos.giftCards.slip.validUntil'), dateOnly(card.expiresOn));
  if (o.receiptNumber !== null) b.pair(t('pos.giftCards.slip.receipt'), o.receiptNumber);
  b.rule();
  b.text(t('pos.giftCards.slip.footer'));
  return b.build();
}
